css:
#agcpt .cp-k{font-family:var(--cps)!important;font-size:12px!important;letter-spacing:.2em!important;color:var(--teal)!important;margin:0 0 12px!important;line-height:1.7!important;font-weight:600!important}
#agcpt .ag-route{margin:22px 0 10px!important;padding:18px 0 14px!important;border-top:1px solid #e6e1d8!important;border-bottom:1px solid #e6e1d8!important}
#agcpt .ag-route-h{font-size:12px!important;letter-spacing:.15em!important;color:#8a8a8a!important;margin:0 0 14px!important;line-height:1.6!important;font-weight:700!important}
#agcpt .ag-route-l{list-style:none!important;margin:0!important;padding:0!important;display:grid!important;grid-template-columns:repeat(6,1fr)!important;gap:0!important}
#agcpt .ag-route-l li{list-style:none!important;position:relative!important;margin:0!important;padding:22px 12px 0 0!important;font-size:12.5px!important;line-height:1.65!important;color:#5d6466!important;word-break:keep-all!important}
#agcpt .ag-route-l li::before{content:''!important;position:absolute!important;left:0!important;top:6px!important;width:8px!important;height:8px!important;border-radius:50%!important;background:var(--teal)!important}
#agcpt .ag-route-l li::after{content:''!important;position:absolute!important;left:14px!important;right:6px!important;top:10px!important;height:1px!important;background:#cfd9d7!important}
#agcpt .ag-route-l li:last-child::after{display:none!important}
#agcpt .ag-route-l li:last-child::before{background:var(--blue)!important}
#agcpt .ag-route-l li span{display:block!important;font-family:var(--cps)!important;font-size:14px!important;font-weight:700!important;color:#1f2a2c!important;margin:0 0 3px!important;letter-spacing:.04em!important}
#agcpt .ag-route-l li:last-child span{color:var(--blue)!important}
#agcpt .ag-art{margin:44px 0!important;background:#fff!important;border:1px solid #e6e1d8!important;border-top:3px solid var(--blue)!important;padding:22px 26px 22px!important}
#agcpt .ag-art-l{font-family:var(--cps)!important;font-size:12px!important;letter-spacing:.24em!important;color:var(--blue)!important;margin:0 0 16px!important;line-height:1.6!important;font-weight:700!important}
#agcpt .ag-art-e+.ag-art-e{border-top:1px solid #eee9df!important;margin-top:22px!important;padding-top:22px!important}
#agcpt .ag-art-has{display:grid!important;grid-template-columns:44% 1fr!important;gap:24px!important;align-items:start!important}
#agcpt .ag-art-f{margin:0!important}
#agcpt .ag-art-f img{display:block!important;width:100%!important;height:auto!important;border:1px solid #ece7dc!important}
#agcpt .ag-art-c{font-size:11.5px!important;line-height:1.6!important;color:#8a8a8a!important;margin:8px 0 0!important}
#agcpt .ag-art-t{display:inline-block!important;font-size:11px!important;letter-spacing:.12em!important;color:var(--teal)!important;border:1px solid #cfe0dd!important;border-radius:20px!important;padding:1px 10px!important;margin:0 0 10px!important;line-height:1.7!important}
#agcpt .ag-art-n{font-family:var(--cps)!important;font-size:19px!important;font-weight:700!important;line-height:1.5!important;color:#1f2a2c!important;margin:0 0 4px!important}
#agcpt .ag-art-w{font-size:13px!important;line-height:1.7!important;color:#6b6f66!important;margin:0 0 12px!important}
#agcpt .ag-art-p{font-size:15px!important;line-height:1.9!important;margin:0 0 12px!important;color:#2b2b2b!important}
#agcpt .ag-art .btns{margin-top:4px!important}
@media (max-width:600px){#agcpt .ag-art-f img[height="1796"]{max-width:62%!important;margin:0 auto!important}#agcpt .ag-route-l{grid-template-columns:1fr!important}#agcpt .ag-route-l li{padding:0 0 12px 22px!important}#agcpt .ag-route-l li::before{top:7px!important}#agcpt .ag-route-l li::after{left:3.5px!important;right:auto!important;top:18px!important;bottom:-2px!important;width:1px!important;height:auto!important}#agcpt .ag-art{padding:18px 18px!important}#agcpt .ag-art-has{grid-template-columns:1fr!important;gap:14px!important}}
